using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

public sealed class DnsApp {
    public sealed record Name(string text, int end);
    public static Name ReadName(int[] b, int start) {
        List<string> labels = new();
        int position = start, end = -1, pointers = 0;
        while (true) {
            int value = (int)LinkNetwork.Integer(b, position, 1);
            if (value == 0) {
                if (end < 0)
                    end = position + 1;
                break;
            }
            if (value >= 192) {
                int low = (int)LinkNetwork.Integer(b, position + 1, 1);
                if (end < 0)
                    end = position + 2;
                if (++pointers > 16)
                    throw new LinkNetwork.Bad("dns: compression loop");
                position = (value - 192) * 256 + low;
                if (position >= b.Length)
                    throw new LinkNetwork.Bad("dns: pointer out of range");
            } else if (value >= 64)
                throw new LinkNetwork.Bad("dns: bad label type");
            else {
                StringBuilder label = new StringBuilder();
                for (int i = 0; i < value; i++) {
                    int c = (int)LinkNetwork.Integer(b, position + 1 + i, 1);
                    if (c >= 33 && c <= 126 && c != 46 && c != 92)
                        label.Append((char)c);
                    else
                        label.Append(string.Format(CultureInfo.InvariantCulture, "\\{0:D3}", c));
                }
                labels.Add(label.ToString());
                position += value + 1;
            }
        }
        return new Name(labels.Count == 0 ? "<root>" : string.Join(".", labels), end);
    }
    public static string Type(long value) {
        return ((int)value) switch {
            1 => "A",
            2 => "NS",
            5 => "CNAME",
            6 => "SOA",
            12 => "PTR",
            15 => "MX",
            16 => "TXT",
            28 => "AAAA",
            _ => "TYPE" + value,
        };
    }
    public static string Rcode(long value) {
        string[] names = { "NoError", "FormErr", "ServFail", "NXDomain", "NotImp", "Refused" };
        return value < names.Length ? names[(int)value] : "RCODE" + value;
    }
    public static string Ipv6(int[] b, int start) {
        List<string> groups = new();
        int best = -1, length = 1;
        for (int i = 0; i < 8; i++)
            groups.Add(LinkNetwork.Word(b, start + 2 * i).ToString("x", CultureInfo.InvariantCulture));
        for (int i = 0; i < 8; i++)
            if (groups[i].Equals("0")) {
                int end = i;
                while (end < 8 && groups[end].Equals("0"))
                    end++;
                if (end - i > length) {
                    best = i;
                    length = end - i;
                }
                i = end - 1;
            }
        if (best < 0)
            return string.Join(":", groups);
        return string.Join(":", groups.GetRange(0, best - (0))) +
               "::" + string.Join(":", groups.GetRange(best + length, 8 - (best + length)));
    }
    public static int[] Dissect(Program.Packet p, int[] b) {
        LinkNetwork.Integer(b, 11, 1);
        int flags = LinkNetwork.Word(b, 2);
        p["dns.id"] = LinkNetwork.Word(b, 0);
        p["dns.flags"] = flags;
        p["dns.flags.response"] = (flags >> 15) & 1;
        p["dns.flags.opcode"] = (flags >> 11) & 15;
        p["dns.flags.rcode"] = flags & 15;
        string[] counts = { "queries", "answers", "auth_rr", "add_rr" };
        for (int i = 0; i < 4; i++)
            p["dns.count." + counts[i]] = LinkNetwork.Word(b, 4 + 2 * i);
        int position = 12;
        for (int i = 0; i < p.Num("dns.count.queries"); i++) {
            Name n = ReadName(b, position);
            LinkNetwork.Integer(b, n.end, 4);
            p.Append("dns.qry.name", n.text);
            p.Append("dns.qry.type", LinkNetwork.Word(b, n.end));
            position = n.end + 4;
        }
        string[] recordFields = { "dns.answer", "dns.authority", "dns.additional" };
        for (int group = 0; group < 3; group++)
            for (int i = 0; i < p.Num("dns.count." + counts[group + 1]); i++) {
                Name n = ReadName(b, position);
                position = n.end;
                LinkNetwork.Integer(b, position + 9, 1);
                int kind = LinkNetwork.Word(b, position), cls = LinkNetwork.Word(b, position + 2),
                    size = LinkNetwork.Word(b, position + 8);
                long ttl = LinkNetwork.Integer(b, position + 4, 4);
                int start = position + 10, end = start + size, read = end;
                if (end > b.Length)
                    throw new LinkNetwork.Bad("dns: truncated");
                string data;
                if (kind == 1) {
                    data = LinkNetwork.Ipv4(LinkNetwork.Integer(b, start, 4));
                    read = start + 4;
                } else if (kind == 28) {
                    data = Ipv6(b, start);
                    read = start + 16;
                } else if (kind == 2 || kind == 5 || kind == 12) {
                    Name target = ReadName(b, start);
                    data = target.text;
                    read = target.end;
                } else if (kind == 15) {
                    int preference = LinkNetwork.Word(b, start);
                    Name target = ReadName(b, start + 2);
                    data = preference + " " + target.text;
                    read = target.end;
                } else if (kind == 6) {
                    Name first = ReadName(b, start), second = ReadName(b, first.end);
                    read = second.end;
                    StringBuilder text = new StringBuilder(first.text + " " + second.text);
                    for (int j = 0; j < 5; j++) {
                        text.Append(" ").Append(LinkNetwork.Integer(b, read, 4));
                        read += 4;
                    }
                    data = text.ToString();
                } else
                    data = size + " bytes";
                if (read != end)
                    throw new LinkNetwork.Bad("dns: bad rdata length");
                p.Append(recordFields[group], n.text + " " + Type(kind) + " " +
                                                  (cls == 1 ? "IN" : "CLASS" + cls) + " " + ttl + " " + data);
                if (group == 0 && kind == 1)
                    p.Append("dns.a", LinkNetwork.Integer(b, start, 4));
                if (group == 0)
                    p.answers.Add(Type(kind) + " " + data);
                position = end;
            }
        return new int[0];
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

public sealed class Flows {
    static int CompareLong(long a, long b) => a.CompareTo(b);
    static long[] GetCounts(Dictionary<long, long[]> counts, long address) {
        if (!counts.TryGetValue(address, out long[] row)) {
            row = new long[4];
            counts[address] = row;
        }
        return row;
    }
    public static readonly string[] MARKS = { "retransmission", "out_of_order", "lost_segment",
                                              "duplicate_ack" };
    public sealed record Endpoint(long address, long port) {
        public override string ToString() {
            return LinkNetwork.Ipv4(address) + (port < 0 ? "" : ":" + port);
        }
    }
    public sealed class Previous {
        public long ack, window;
        public int number, count;
        public Previous(long ack, long window, int number) {
            this.ack = ack;
            this.window = window;
            this.number = number;
        }
    }
    public sealed class Side {
        public string name;
        public long isn = -1, mss = -1, ws = -1, sequenceBase = -1, expected = -1, advanced, packets, payload;
        public HashSet<string> intervals = new();
        public Previous previous;
        public long[] marks = new long[4];
        public Side(string name) {
            this.name = name;
        }
    }
    public sealed class Stream {
        public int number, syn = -1, synAck = -1, ack = -1;
        public Endpoint client, server;
        public string state;
        public Side clientSide = new Side("client"), serverSide = new Side("server"), closer;
        public long start, end, packets, bytes, finalAck;
        public List<string> history = new(), events = new();
        public Stream(int number, Endpoint client, Endpoint server, string state, Program.Packet p) {
            this.number = number;
            this.client = client;
            this.server = server;
            this.state = state;
            start = p.time;
            Change(state, p.number);
        }
        public void Change(string state, int number) {
            this.state = state;
            history.Add(state + " " + number);
        }
        public void Record(Side side, Program.Packet p) {
            side.isn = p.Num("tcp.seq_raw");
            side.mss = p.Has("tcp.options.mss") ? p.Num("tcp.options.mss") : -1;
            side.ws = p.Has("tcp.options.wscale") ? p.Num("tcp.options.wscale") : -1;
            if (side == clientSide)
                syn = p.number;
            else
                synAck = p.number;
        }
    }
    public readonly List<Stream> streams = new();
    public void Track(Program.Packet p) {
        Endpoint source = new Endpoint(p.Num("ip.src"), p.Num("tcp.srcport")),
                 destination = new Endpoint(p.Num("ip.dst"), p.Num("tcp.dstport"));
        bool syn = p.Num("tcp.flags.syn") == 1, ackSet = p.Num("tcp.flags.ack") == 1,
             fin = p.Num("tcp.flags.fin") == 1, rst = p.Num("tcp.flags.rst") == 1;
        long seq = p.Num("tcp.seq_raw"), ack = ackSet ? p.Num("tcp.ack_raw") : 0;
        Stream stream = null;
        for (int i = streams.Count - 1; i >= 0; i--) {
            Stream candidate = streams[i];
            if ((candidate.client.Equals(source) && candidate.server.Equals(destination)) ||
                (candidate.client.Equals(destination) && candidate.server.Equals(source))) {
                stream = candidate;
                break;
            }
        }
        if (stream == null ||
            ((stream.state.Equals("CLOSED") || stream.state.Equals("RESET")) && syn && !ackSet)) {
            stream = new Stream(streams.Count, syn && ackSet ? destination : source,
                                syn && ackSet ? source : destination,
                                syn ? (ackSet ? "SYN_RECEIVED" : "SYN_SENT") : "ESTABLISHED", p);
            if (syn)
                stream.Record(ackSet ? stream.serverSide : stream.clientSide, p);
            streams.Add(stream);
        }
        p["tcp.stream"] = stream.number;
        Side side = source.Equals(stream.client) ? stream.clientSide : stream.serverSide,
             other = side == stream.clientSide ? stream.serverSide : stream.clientSide;
        if (side.sequenceBase < 0)
            side.sequenceBase = seq;
        if (ackSet && other.sequenceBase < 0)
            other.sequenceBase = ack;
        long relative = (seq - side.sequenceBase + 4294967296L) % 4294967296L;
        p["tcp.seq"] = relative;
        if (ackSet)
            p["tcp.ack"] = (ack - other.sequenceBase + 4294967296L) % 4294967296L;
        long size = p.Num("tcp.len") + (syn ? 1 : 0) + (fin ? 1 : 0);
        int mark = -1;
        if (size >= 1) {
            if (side.expected >= 0 && relative != side.expected) {
                if (relative > side.expected)
                    mark = 2;
                else if (side.intervals.Contains(relative + ":" + size))
                    mark = 0;
                else
                    mark = p.time - side.advanced < 3000 ? 1 : 0;
            }
            side.intervals.Add(relative + ":" + size);
            if (side.expected < 0 || relative + size > side.expected) {
                side.expected = relative + size;
                side.advanced = p.time;
            }
        } else if (ackSet && !rst && side.previous != null && ack == side.previous.ack &&
                   p.Num("tcp.window") == side.previous.window) {
            mark = 3;
            side.previous.count++;
            p.duplicate = "[TCP Dup ACK " + side.previous.number + "#" + side.previous.count + "] ";
        }
        if (ackSet && mark != 3)
            side.previous = new Previous(ack, p.Num("tcp.window"), p.number);
        if (mark >= 0) {
            p["tcp.analysis." + MARKS[mark]] = 0;
            side.marks[mark]++;
            stream.events.Add("event " + p.number + " " + side.name + " " + MARKS[mark] + " seq " + relative +
                              " len " + size);
        }
        p["tcp.window.calc"] =
            p.Num("tcp.window") *
            (stream.clientSide.ws >= 0 && stream.serverSide.ws >= 0 && !syn ? 1L << (int)side.ws : 1);
        if (rst) {
            if (!stream.state.Equals("CLOSED") && !stream.state.Equals("RESET"))
                stream.Change("RESET", p.number);
        } else if (stream.state.Equals("SYN_SENT") && side == stream.serverSide && syn && ackSet &&
                   ack == (stream.clientSide.isn + 1) % 4294967296L) {
            stream.Change("SYN_RECEIVED", p.number);
            stream.Record(side, p);
        } else if (stream.state.Equals("SYN_RECEIVED") && side == stream.clientSide && ackSet && !syn &&
                   ack == (stream.serverSide.isn + 1) % 4294967296L) {
            stream.Change("ESTABLISHED", p.number);
            stream.ack = p.number;
        } else if (stream.state.Equals("ESTABLISHED") && fin) {
            stream.Change("FIN_WAIT", p.number);
            stream.closer = side;
        } else if (stream.state.Equals("FIN_WAIT") && fin && side != stream.closer) {
            stream.Change("CLOSING", p.number);
            stream.finalAck = (seq + p.Num("tcp.len") + 1) % 4294967296L;
        } else if (stream.state.Equals("CLOSING") && side == stream.closer && ackSet &&
                   ack == stream.finalAck)
            stream.Change("CLOSED", p.number);
        side.packets++;
        side.payload += p.Num("tcp.len");
        stream.packets++;
        stream.bytes += p.length;
        stream.end = p.time;
    }
    public sealed class Conversation {
        public string kind;
        public Endpoint a, b;
        public int first;
        public long start, end;
        public long[] packets = new long[2], bytes = new long[2];
        public Conversation(string kind, Endpoint a, Endpoint b, Program.Packet p) {
            this.kind = kind;
            this.a = a;
            this.b = b;
            first = p.number;
            start = p.time;
        }
        public long TotalBytes() {
            return bytes[0] + bytes[1];
        }
        public long TotalPackets() {
            return packets[0] + packets[1];
        }
    }
    public static List<string> Conversations(List<Program.Packet> packets) {
        Dictionary<string, Conversation> grouped = new();
        foreach (Program.Packet p in packets)
            foreach (string kind in new string[] { "ipv4", "tcp", "udp" }) {
                if (!p.Has(kind.Equals("ipv4")  ? "ip.src"
                           : kind.Equals("tcp") ? "tcp.stream"
                                                : "udp.srcport"))
                    continue;
                Endpoint source = new Endpoint(p.Num("ip.src"),
                                               kind.Equals("ipv4") ? -1 : p.Num(kind + ".srcport")),
                         destination = new Endpoint(p.Num("ip.dst"),
                                                    kind.Equals("ipv4") ? -1 : p.Num(kind + ".dstport"));
                string first = source.ToString(), second = destination.ToString();
                string key = kind + ":" +
                             (kind.Equals("tcp") ? p.Num("tcp.stream").ToString(CultureInfo.InvariantCulture)
                              : string.CompareOrdinal(first, second) < 0 ? first + ":" + second
                                                                         : second + ":" + first);
                Conversation c = grouped.GetValueOrDefault(key);
                if (c == null) {
                    c = new Conversation(kind, source, destination, p);
                    grouped[key] = c;
                }
                int direction = source.Equals(c.a) ? 0 : 1;
                c.packets[direction]++;
                c.bytes[direction] += p.length;
                c.end = p.time;
            }
        List<Conversation> ordered = new(grouped.Values);
        ordered.Sort((a, b) =>
                         a.TotalBytes() != b.TotalBytes()       ? b.TotalBytes().CompareTo(a.TotalBytes())
                         : a.TotalPackets() != b.TotalPackets() ? b.TotalPackets().CompareTo(a.TotalPackets())
                         : a.kind != b.kind
                             ? Array.IndexOf(new string[] { "ipv4", "tcp", "udp" }, a.kind)
                                   .CompareTo(Array.IndexOf(new string[] { "ipv4", "tcp", "udp" }, b.kind))
                             : a.first.CompareTo(b.first));
        List<string> output = new();
        output.Add(
            "type,endpoint_a,endpoint_b,packets,bytes,packets_a_to_b,bytes_a_to_b,packets_b_to_a,bytes_b_to_a,start,duration");
        long origin = packets[0].time;
        foreach (Conversation c in ordered)
            output.Add(c.kind + "," + c.a + "," + c.b + "," + c.TotalPackets() + "," + c.TotalBytes() + "," +
                       c.packets[0] + "," + c.bytes[0] + "," + c.packets[1] + "," + c.bytes[1] + "," +
                       Program.Seconds(c.start - origin) + "," + Program.Seconds(c.end - c.start));
        return output;
    }
    public static List<string> Endpoints(List<Program.Packet> packets) {
        Dictionary<long, long[]> counts = new();
        foreach (Program.Packet p in packets)
            if (p.Has("ip.src"))
                for (int side = 0; side < 2; side++) {
                    long address = p.Num(side == 0 ? "ip.src" : "ip.dst");
                    long[] row = GetCounts(counts, address);
                    row[side * 2]++;
                    row[side * 2 + 1] += p.length;
                }
        List<long> ordered = new(counts.Keys);
        ordered.Sort((a, b) => {
            long[] x = counts[a], y = counts[b];
            int c = CompareLong(y[1] + y[3], x[1] + x[3]);
            if (c == 0)
                c = CompareLong(y[0] + y[2], x[0] + x[2]);
            return c != 0 ? c : CompareLong(a, b);
        });
        List<string> output = new();
        output.Add("address,packets,bytes,tx_packets,tx_bytes,rx_packets,rx_bytes");
        foreach (long address in ordered) {
            long[] row = counts[address];
            output.Add(LinkNetwork.Ipv4(address) + "," + (row[0] + row[2]) + "," + (row[1] + row[3]) + "," +
                       row[0] + "," + row[1] + "," + row[2] + "," + row[3]);
        }
        return output;
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

public sealed class Hexdump {
    public static List<Program.Packet> Read() {
        List<string> lines = File.ReadAllLines(Path.Combine("input/capture.txt"), Encoding.ASCII).ToList();
        List<Program.Packet> packets = new();
        Program.Packet packet = null;
        List<int> bytes = new();
        for (int line = 0; line <= lines.Count; line++) {
            string text = line < lines.Count ? lines[line] : "PACKET ";
            if (text.StartsWith("PACKET ")) {
                if (packet != null) {
                    if (packet.reason == null && bytes.Count != packet.length)
                        packet.reason =
                            "dump: length mismatch (header " + packet.length + ", data " + bytes.Count + ")";
                    packet.bytes = bytes.ToArray();
                    packets.Add(packet);
                }
                if (line == lines.Count)
                    break;
                string[] parts = text.Split(" ");
                packet = new Program.Packet(int.Parse(parts[1]), long.Parse(parts[2]), int.Parse(parts[3]));
                bytes = new();
            } else if (text.Length != 0 && packet.reason == null) {
                if (!Regex.IsMatch(text, "\\A[0-9a-f]{4}  [0-9a-f]{2}( [0-9a-f]{2}){0,15}\\z"))
                    packet.reason = "dump: bad line " + (line + 1);
                else if (System.Convert.ToInt32(text.Substring(0, 4), 16) != bytes.Count)
                    packet.reason = "dump: offset mismatch at line " + (line + 1);
                else
                    foreach (string value in text.Substring(6).Split(" "))
                        bytes.Add(System.Convert.ToInt32(value, 16));
            }
        }
        return packets;
    }
    public static List<string> Lines(int[] bytes) {
        List<string> output = new();
        for (int start = 0; start < bytes.Length; start += 16) {
            List<string> hex = new();
            StringBuilder text = new StringBuilder();
            for (int i = start; i < Math.Min(start + 16, bytes.Length); i++) {
                hex.Add(string.Format(CultureInfo.InvariantCulture, "{0:x2}", bytes[i]));
                text.Append(bytes[i] >= 32 && bytes[i] <= 126 ? (char)bytes[i] : '.');
            }
            output.Add(string.Format(CultureInfo.InvariantCulture, "{0:x4}  {1,-47}  |{2}|", start,
                                     string.Join(" ", hex), text));
        }
        return output;
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

public sealed class LinkNetwork {
    public sealed class Bad : Exception {
        public Bad(string reason) : base(reason) {
        }
    }
    public static long Integer(int[] bytes, int position, int count) {
        if (position < 0 || position + count > bytes.Length)
            throw new Bad("dns: truncated");
        long value = 0;
        for (int i = 0; i < count; i++)
            value = value * 256 + bytes[position + i];
        return value;
    }
    public static int Word(int[] bytes, int position) {
        return (int)Integer(bytes, position, 2);
    }
    public static int[] Slice(int[] bytes, int start, int end) {
        return bytes[start..end];
    }
    public static string Checksum(int[] bytes) {
        long sum = 0;
        for (int i = 0; i < bytes.Length; i += 2)
            sum += bytes[i] * 256 + (i + 1 < bytes.Length ? bytes[i + 1] : 0);
        while (sum > 65535)
            sum = (sum & 65535) + (sum >> 16);
        return sum == 65535 ? "good" : "bad";
    }
    public static string Ipv4(long value) {
        return ((value >> 24) & 255) + "." + ((value >> 16) & 255) + "." + ((value >> 8) & 255) + "." +
               (value & 255);
    }
    public static string Mac(long value) {
        List<string> parts = new();
        for (int shift = 40; shift >= 0; shift -= 8)
            parts.Add(string.Format(CultureInfo.InvariantCulture, "{0:x2}", (value >> shift) & 255));
        return string.Join(":", parts);
    }
    public static int[] Ethernet(Program.Packet p, int[] b) {
        if (b.Length < 14)
            throw new Bad("eth: truncated");
        p["eth.dst"] = Integer(b, 0, 6);
        p["eth.src"] = Integer(b, 6, 6);
        p["eth.type"] = Word(b, 12);
        return Slice(b, 14, b.Length);
    }
    public static int[] Arp(Program.Packet p, int[] b) {
        if (b.Length < 28)
            throw new Bad("arp: truncated");
        if (Word(b, 0) != 1 || Word(b, 2) != 2048 || b[4] != 6 || b[5] != 4)
            throw new Bad("arp: unsupported format");
        p["arp.opcode"] = Word(b, 6);
        p["arp.src.hw"] = Integer(b, 8, 6);
        p["arp.src.ip"] = Integer(b, 14, 4);
        p["arp.dst.hw"] = Integer(b, 18, 6);
        p["arp.dst.ip"] = Integer(b, 24, 4);
        return new int[0];
    }
    public static int[] Ipv4(Program.Packet p, int[] b) {
        if (b.Length < 20)
            throw new Bad("ip: truncated header");
        int version = b[0] / 16, h = b[0] % 16 * 4;
        if (version != 4)
            throw new Bad("ip: bad version " + version);
        if (h < 20)
            throw new Bad("ip: bad header length " + h);
        if (b.Length < h)
            throw new Bad("ip: truncated header");
        int total = Word(b, 2);
        if (total < h)
            throw new Bad("ip: bad total length " + total);
        if (total > b.Length)
            throw new Bad("ip: truncated (total length " + total + ", available " + b.Length + ")");
        int flags = Word(b, 6);
        p["ip.hdr_len"] = h;
        p["ip.tos"] = b[1];
        p["ip.len"] = total;
        p["ip.id"] = Word(b, 4);
        p["ip.flags.df"] = (flags >> 14) & 1;
        p["ip.flags.mf"] = (flags >> 13) & 1;
        p["ip.frag_offset"] = flags % 8192 * 8;
        p["ip.ttl"] = b[8];
        p["ip.proto"] = b[9];
        p["ip.checksum"] = Word(b, 10);
        p["ip.checksum.status"] = Checksum(Slice(b, 0, h));
        p["ip.src"] = Integer(b, 12, 4);
        p["ip.dst"] = Integer(b, 16, 4);
        if ((flags & 8192) != 0 || flags % 8192 != 0)
            p["ip.fragment"] = 0;
        return Slice(b, h, total);
    }
}

using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Text.RegularExpressions;

public static class Program {
    static int CompareLong(long a, long b) => a.CompareTo(b);
    public sealed class Packet {
        public object this[string name] {
            set {
