    public static string Type(string name) {
        foreach (string[] row in FIELDS)
            if (row[0].Equals(name))
                return row[1];
        foreach (string[] row in ALIASES)
            if (row[0].Equals(name))
                return row[1];
        return PROTOCOLS.Contains(name) ? "presence" : null;
    }
